def require_role(role: str, p: CurrentPrincipal) -> None:
    if p.is_anonymous or role not in p.roles:
        raise PermissionError(role)

anon = CurrentPrincipal('', None, frozenset(), {}, True)
assert anon.is_anonymous

def extract(headers: dict[str, str]) -> CorrelationId:
    raw = headers.get('x-request-id') or headers.get('traceparent', '')
    return CorrelationId(raw) if raw else CorrelationId('gen-xyz')

log_ctx: dict[str, str] = {'corr': extract({'x-request-id': 'abc'})}

async def timing(ctx: RequestContext, call_next: Next) -> None:
    t0 = 0.0
    await call_next()
    ctx.put('elapsed_ms', t0)

def build(p: MiddlewarePipeline) -> MiddlewarePipeline:
    return p.use(timing)

