from typing import Protocol

class RequestGuard(Protocol):
    async def allow(self, ctx: RequestContext, principal: CurrentPrincipal) -> bool: ...

primitives.consumption_example:
class RoleGuard:
    def __init__(self, role: str) -> None:
        self.role = role
    async def allow(self, ctx: RequestContext, principal: CurrentPrincipal) -> bool:
        return not principal.is_anonymous and self.role in principal.roles

g: RequestGuard = RoleGuard('admin')

class ParseInt:
    def transform(self, value: str, meta: ArgumentMetadata) -> int:
        return int(value)

meta = ArgumentMetadata(kind='param', metatype=int, data='id')
v: ValueTransform = ParseInt()
assert v.transform('7', meta) == 7

